static inline void cyw43_arch_lwip_begin(void) {
    cyw43_thread_enter();
}
static inline void cyw43_arch_lwip_end(void) {
    cyw43_thread_exit();
}
static inline int cyw43_arch_lwip_protect(int (*func)(void *param), void *param) {
    cyw43_arch_lwip_begin();
    int rc = func(param);
    cyw43_arch_lwip_end();
    return rc;
}
